    if not arr:
        return None

    magnitude_sum = sum(abs(num) for num in arr)
    sign_product = 1
    for num in arr:
        if num == 0:
            sign_product = 0
            break
        elif num < 0:
            sign_product *= -1

    return magnitude_sum * sign_product
