def tri(n):
    result = [0, 1, 1]
    if n == 0:
        return [0]
    elif n == 1:
        return result[:2]

    for i in range(3, n + 1):
        if i % 2 == 0:
            result.append(1 + i // 2)
        else:
            result.append(sum(result[i - 2:i + 1]))

    return result
