def fix_spaces(text):
    result = ""
    consecutive_spaces = 0
    for i in range(len(text)):
        if text[i] == " ":
            consecutive_spaces += 1
            if consecutive_spaces > 2:
                if result[-1] != "-":
                    result += "-"
            else:
                result += "_"
        else:
            consecutive_spaces = 0
            result += text[i]
    if text[0] == " ":
        result = "_" + result[1:]
    if text[-1] == " ":
        result = result[:-1] + "_"
    return result

