def int_to_mini_roman(number):
    roman_dict = {
        'i': 1, 'iv': 4, 'v': 5, 'ix': 9, 'x': 10, 
        'xl': 40, 'l': 50, 'xc': 90, 'c': 100, 
        'cd': 400, 'd': 500, 'cm': 900, 'm': 1000
    }

    result = ''

    for roman_numeral, value in sorted(roman_dict.items(), key=lambda x: -x[1]):
        while number >= value:
            result += roman_numeral
            number -= value

    return result
