def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
    return result

def solve(s):
    result = ""
    has_letter = False

    for char in s:
        if char.isalpha():
            has_letter = True
            result += char.swapcase()
        else:
            result += char

    if not has_letter:
        result = result[::-1]

    return result

